#!/usr/bin/env python3
"""Render an offline human-readable cover sheet from a verified inspection packet.
No remote resources, scripts, telemetry, new claims or new measurement execution.
"""
import argparse,html,json
from pathlib import Path
from inspection_packet import verify_packet

def render_report(raw:bytes,request_id:str|None=None,expected_sha256:str|None=None)->str:
    r=verify_packet(raw,request_id,expected_sha256)
    esc=lambda value:html.escape(str(value),quote=True)
    count='Not a row-indexed collection' if r['records_recounted'] is None else str(r['records_recounted'])
    rows=''.join('<tr><td>'+esc(k)+'</td><td>'+str(v)+'</td></tr>' for k,v in sorted(r['recorded_state_counts_recounted'].items())) or '<tr><td>No row-level status distribution in this source</td><td>Not applicable</td></tr>'
    facts=[('Request',r['request_id']),('Packet SHA-256',r['packet_sha256']),('Delivered result SHA-256',r['delivery_sha256']),('Exact source SHA-256',r['source_sha256']),('Retained observation SHA-256',r['observation_sha256']),('Method source SHA-256',r['method_sha256']),('Full request record SHA-256',r['full_request_record_sha256'])]
    facts=''.join('<dt>'+esc(k)+'</dt><dd><code>'+esc(v)+'</code></dd>' for k,v in facts)
    command='python3 inspection_packet.py verify inspection-'+r['request_id']+'.zip --expected-request-id '+r['request_id']+' --expected-sha256 '+r['packet_sha256']
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>CSOAI — retained evidence inspection</title><style>
:root{font-family:Arial,sans-serif;color:#182838;background:#f1f4f6}*{box-sizing:border-box}body{margin:0}main{max-width:1000px;margin:40px auto;padding:38px;background:white;border:1px solid #d8e1e8;border-radius:18px}header{border-bottom:3px solid #173e45;padding-bottom:22px}.eyebrow{font-size:12px;letter-spacing:1.5px;font-weight:bold;color:#36575a}h1{font-size:36px;line-height:1.12;margin:12px 0}h2{font-size:22px;margin-top:30px}p,li{line-height:1.6}.muted{color:#536573}.badge{display:inline-block;background:#fff4da;color:#604c15;padding:8px 12px;border-radius:7px;font-size:12px;font-weight:bold}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:24px 0}.metric{background:#edf3f4;border-radius:10px;padding:20px}.metric strong{display:block;font-size:26px;margin-top:8px}table{width:100%;border-collapse:collapse;margin:16px 0}td,th{text-align:left;padding:11px;border-bottom:1px solid #d9e3e8}th{font-size:12px;text-transform:uppercase}dt{font-weight:bold;margin-top:14px;font-size:13px}dd{margin:5px 0}code,pre{overflow-wrap:anywhere;white-space:pre-wrap;word-break:break-all;font-size:12px}pre{background:#edf3f4;border-radius:8px;padding:16px}.scope{border-left:4px solid #b17a18;background:#fff9ed;padding:14px 18px}footer{border-top:1px solid #d8e1e8;margin-top:32px;padding-top:18px;font-size:12px;color:#536573}@media(max-width:640px){main{margin:0;padding:22px;border-radius:0}.metrics{grid-template-columns:1fr}h1{font-size:29px}}@media print{body{background:white}main{margin:0;border:0;padding:10px}}
</style></head><body><main><header><div class="eyebrow">COUNCIL OF AI · PRIVATE INSPECTION DEMONSTRATION</div><h1>Evidence you can inspect.</h1><p class="muted">A portable check of an existing source-evidence delivery. This page is a cover sheet; the packet and verifier carry the reproducible checks.</p><span class="badge">SELF-CONSISTENT · UNSIGNED · NOT A CERTIFICATION</span></header>'''+f'''<section class="metrics"><div class="metric">Retained collection<strong>{esc(r['source_id'])}</strong></div><div class="metric">Records independently recounted<strong>{esc(count)}</strong></div></section><p><strong>Source date:</strong> {esc(r.get('source_as_of') or 'Not recorded')}. Exporting or opening this report does not make the source newer.</p><p><strong>Recorded source:</strong> <code>{esc(r['source_url'])}</code></p>
<section class="scope"><strong>Read this distinction first.</strong><p>A source row labelled MEASURED is a label in the retained source, not a new measurement by this verifier. This packet does not establish organisational safety, legal compliance, asset reserves, redemption, settlement or deployment authority. Its publisher is not authenticated by the packet's own hashes.</p></section>
<h2>What the source recorded</h2><table><thead><tr><th>Original status label</th><th>Recounted rows</th></tr></thead><tbody>{rows}</tbody></table>
<h2>What was checked</h2><p>The packet contains the exact request, delivered result, source bytes, observation record and method/observer source files. The verifier checks their digests and cross-references, independently recounts row identities and statuses where applicable, and rejects mismatched scope, dates, counts, budgets or authority claims. It never runs code included in the packet.</p>
<h2>What was not checked</h2><p>No new model evaluation or live ledger read occurred. No issuer signature, chain inclusion or legal finding was verified. Independent reviewer approval and customer acceptance are not supplied by this cover sheet. A checksum received through the same untrusted packet is not independent evidence of identity.</p>
<h2>Reproduce the packet check</h2><p>Obtain the verifier and expected request/digest through a trusted channel. Run the following on the packet without executing its bundled method files.</p><pre>{esc(command)}</pre>
<h2>Evidence identifiers</h2><dl>{facts}</dl>
<h2>Acceptance for a scoped pilot</h2><p>The recipient should be able to retrieve the packet, reproduce the checks, identify source dates and limitations, and raise a specific discrepancy. A commercial service requires a separately agreed scope, authority, human review and acceptance. The present packet demonstrates a working evidence-export workflow, not a completed customer engagement.</p>
<footer>Private review artefact. Not publicly released. Verification is separate from evidence production, payment, admission, signing and witnessing. No external resources or analytics are loaded by this page.</footer></main></body></html>'''

if __name__=='__main__':
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('packet',type=Path);p.add_argument('--out',type=Path,required=True);p.add_argument('--expected-request-id');p.add_argument('--expected-sha256');a=p.parse_args()
 content=render_report(a.packet.read_bytes(),a.expected_request_id,a.expected_sha256)
 with a.out.open('x',encoding='utf-8') as f:f.write(content)
 print(json.dumps({'state':'RENDERED_FROM_VERIFIED_PACKET','path':str(a.out),'new_measurements':0,'public':False}))
